import React, { useEffect, useState } from "react";
import Sidebar from "../components/Sidebar";

function Dashboard() {
  const [stats, setStats] = useState(null);
  const [upcomingSessions, setUpcomingSessions] = useState([]);
  const [recentActivity, setRecentActivity] = useState([]);
  const [loading, setLoading] = useState(true);
  const [currentMonth, setCurrentMonth] = useState(new Date());

  const user = JSON.parse(localStorage.getItem("user"));

  useEffect(() => {
    if (!user) return;

    async function loadDashboard() {
      try {
        const res = await fetch(`http://localhost:8080/dashboard/${user.id}`);
        const data = await res.json();

        setStats(data.stats);
        setUpcomingSessions(data.upcomingSessions);
        setRecentActivity(data.recentActivity);
        setLoading(false);
      } catch (err) {
        console.error("Dashboard error:", err);
        // Set mock data for demonstration
        setStats({
          xp: 2450,
          coins: 125,
          streak: 7,
          lessonsCompleted: 12,
          lessonsInProgress: 8,
          totalGameScore: 3540,
        });
        setUpcomingSessions([
          { id: 1, subject: "Biology", tutorName: "Ms. Johnson", session_time: new Date(Date.now() + 86400000) },
          { id: 2, subject: "Chemistry", tutorName: "Mr. Smith", session_time: new Date(Date.now() + 172800000) },
        ]);
        setRecentActivity([
          { id: 1, type: "Game Won", description: "Completed Cell Structure Master", subject: "Biology", created_at: new Date() },
          { id: 2, type: "Lesson Completed", description: "Finished Photosynthesis lesson", subject: "Biology", created_at: new Date(Date.now() - 3600000) },
        ]);
        setLoading(false);
      }
    }

    loadDashboard();
  }, [user]);

  // Calendar helper functions
  const getDaysInMonth = (date) => new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  const getFirstDayOfMonth = (date) => new Date(date.getFullYear(), date.getMonth(), 1).getDay();

  const renderCalendar = () => {
    const daysInMonth = getDaysInMonth(currentMonth);
    const firstDay = getFirstDayOfMonth(currentMonth);
    const days = [];

    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`} className="calendar-day empty"></div>);
    }

    for (let i = 1; i <= daysInMonth; i++) {
      const isToday = i === new Date().getDate() && currentMonth.getMonth() === new Date().getMonth();
      days.push(
        <div key={i} className={`calendar-day ${isToday ? "today" : ""}`}>
          {i}
        </div>
      );
    }

    return days;
  };

  if (!user) {
    return <h1 style={{ color: "white" }}>Please log in</h1>;
  }

  const lessonProgress = stats ? (stats.lessonsCompleted / (stats.lessonsCompleted + stats.lessonsInProgress)) * 100 : 0;
  const xpProgress = stats ? (stats.xp % 1000) / 10 : 0;

  return (
    <div className="dashboard-page">
      <Sidebar />

      <main className="dashboard-main" style={{ padding: "2rem", maxWidth: "100%" }}>
        {/* HERO SECTION */}
        <header style={{
          background: "linear-gradient(135deg, rgba(14, 165, 233, 0.1) 0%, rgba(56, 189, 248, 0.05) 100%)",
          border: "1px solid rgba(56, 189, 248, 0.2)",
          backdropFilter: "blur(10px)",
          borderRadius: "16px",
          padding: "2rem",
          marginBottom: "3rem",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}>
          <div>
            <h1 style={{ fontSize: "2.5rem", color: "#f9fafb", marginBottom: "0.5rem", fontWeight: "700" }}>
              Welcome back, {user.firstName}! 👋
            </h1>
            <p style={{ fontSize: "1.1rem", color: "#9ca3af" }}>
              Keep up your streak and continue mastering new subjects
            </p>
          </div>
          <div style={{ textAlign: "center" }}>
            <div style={{ fontSize: "3.5rem", fontWeight: "700", color: "#fcd34d" }}>
              🔥 {stats?.streak || 0}
            </div>
            <div style={{ color: "#9ca3af", fontSize: "0.9rem" }}>Day Streak</div>
          </div>
        </header>

        {loading ? (
          <p style={{ color: "#9ca3af", textAlign: "center" }}>Loading...</p>
        ) : stats ? (
          <>
            {/* TOP STATS ROW */}
            <div style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
              gap: "1.5rem",
              marginBottom: "2rem",
            }}>
              {/* XP Card */}
              <div style={{
                background: "linear-gradient(135deg, rgba(34, 197, 94, 0.1) 0%, rgba(22, 163, 74, 0.05) 100%)",
                border: "1px solid rgba(34, 197, 94, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <div style={{ color: "#9ca3af", fontSize: "0.9rem", marginBottom: "0.5rem" }}>📊 Total XP</div>
                <div style={{ fontSize: "2rem", fontWeight: "700", color: "#86efac", marginBottom: "1rem" }}>
                  {stats.xp || 0}
                </div>
                <div style={{ background: "rgba(0,0,0,0.2)", borderRadius: "8px", height: "6px", overflow: "hidden" }}>
                  <div style={{
                    width: `${xpProgress}%`,
                    height: "100%",
                    background: "linear-gradient(90deg, #86efac, #22c55e)",
                    transition: "width 0.3s ease",
                  }}></div>
                </div>
                <div style={{ color: "#6b7280", fontSize: "0.75rem", marginTop: "0.5rem" }}>
                  {Math.floor(stats.xp % 1000)} / 1000
                </div>
              </div>

              {/* Coins Card */}
              <div style={{
                background: "linear-gradient(135deg, rgba(252, 211, 77, 0.1) 0%, rgba(217, 119, 6, 0.05) 100%)",
                border: "1px solid rgba(252, 211, 77, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <div style={{ color: "#9ca3af", fontSize: "0.9rem", marginBottom: "0.5rem" }}>💰 Coins</div>
                <div style={{ fontSize: "2rem", fontWeight: "700", color: "#fcd34d", marginBottom: "1rem" }}>
                  {stats.coins}
                </div>
                <div style={{ color: "#6b7280", fontSize: "0.85rem" }}>
                  💎 Next Reward: 50 coins
                </div>
              </div>

              {/* Lessons Card */}
              <div style={{
                background: "linear-gradient(135deg, rgba(59, 130, 246, 0.1) 0%, rgba(37, 99, 235, 0.05) 100%)",
                border: "1px solid rgba(59, 130, 246, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <div style={{ color: "#9ca3af", fontSize: "0.9rem", marginBottom: "0.5rem" }}>📚 Lessons</div>
                <div style={{ fontSize: "2rem", fontWeight: "700", color: "#60a5fa", marginBottom: "1rem" }}>
                  {stats.lessonsCompleted}/{stats.lessonsCompleted + stats.lessonsInProgress}
                </div>
                <div style={{ background: "rgba(0,0,0,0.2)", borderRadius: "8px", height: "6px", overflow: "hidden" }}>
                  <div style={{
                    width: `${lessonProgress}%`,
                    height: "100%",
                    background: "linear-gradient(90deg, #60a5fa, #3b82f6)",
                    transition: "width 0.3s ease",
                  }}></div>
                </div>
                <div style={{ color: "#6b7280", fontSize: "0.75rem", marginTop: "0.5rem" }}>
                  {Math.floor(lessonProgress)}% Complete
                </div>
              </div>

              {/* Game Score Card */}
              <div style={{
                background: "linear-gradient(135deg, rgba(168, 85, 247, 0.1) 0%, rgba(126, 34, 206, 0.05) 100%)",
                border: "1px solid rgba(168, 85, 247, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <div style={{ color: "#9ca3af", fontSize: "0.9rem", marginBottom: "0.5rem" }}>🎮 Game Score</div>
                <div style={{ fontSize: "2rem", fontWeight: "700", color: "#d8b4fe", marginBottom: "1rem" }}>
                  {stats.totalGameScore || 0}
                </div>
                <div style={{ color: "#6b7280", fontSize: "0.85rem" }}>
                  📈 +250 this week
                </div>
              </div>
            </div>

            {/* MIDDLE SECTION - CALENDAR & ACTIVITY CHART */}
            <div style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "1.5rem",
              marginBottom: "2rem",
            }}>
              {/* CALENDAR */}
              <div style={{
                background: "rgba(15, 23, 42, 0.5)",
                border: "1px solid rgba(148, 163, 184, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.5rem" }}>
                  <h3 style={{ color: "#f9fafb", fontSize: "1.2rem", fontWeight: "600" }}>📅 Calendar</h3>
                  <div style={{ display: "flex", gap: "0.5rem" }}>
                    <button onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1))}
                      style={{
                        padding: "5px 10px",
                        background: "rgba(148, 163, 184, 0.1)",
                        border: "1px solid rgba(148, 163, 184, 0.2)",
                        color: "#9ca3af",
                        borderRadius: "6px",
                        cursor: "pointer",
                      }}>←</button>
                    <button onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1))}
                      style={{
                        padding: "5px 10px",
                        background: "rgba(148, 163, 184, 0.1)",
                        border: "1px solid rgba(148, 163, 184, 0.2)",
                        color: "#9ca3af",
                        borderRadius: "6px",
                        cursor: "pointer",
                      }}>→</button>
                  </div>
                </div>
                <div style={{ color: "#9ca3af", marginBottom: "1rem", textAlign: "center", fontSize: "0.95rem", fontWeight: "600" }}>
                  {currentMonth.toLocaleString("default", { month: "long", year: "numeric" })}
                </div>
                <div style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(7, 1fr)",
                  gap: "0.5rem",
                }}>
                  {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => (
                    <div key={day} style={{ color: "#6b7280", fontSize: "0.75rem", textAlign: "center", fontWeight: "600" }}>
                      {day}
                    </div>
                  ))}
                  {renderCalendar()}
                </div>
                <style>{`
                  .calendar-day {
                    padding: 8px;
                    background: rgba(148, 163, 184, 0.1);
                    border-radius: 6px;
                    color: #9ca3af;
                    textAlign: center;
                    fontSize: 0.85rem;
                    cursor: pointer;
                    transition: all 0.2s;
                  }
                  .calendar-day:hover {
                    background: rgba(56, 189, 248, 0.2);
                    color: #38bdf8;
                  }
                  .calendar-day.today {
                    background: linear-gradient(135deg, #38bdf8, #0ea5e9);
                    color: white;
                    fontWeight: 700;
                  }
                  .calendar-day.empty {
                    background: transparent;
                    cursor: default;
                  }
                  .calendar-day.empty:hover {
                    background: transparent;
                    color: #9ca3af;
                  }
                `}</style>
              </div>

              {/* ACHIEVEMENT BADGES */}
              <div style={{
                background: "rgba(15, 23, 42, 0.5)",
                border: "1px solid rgba(148, 163, 184, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <h3 style={{ color: "#f9fafb", fontSize: "1.2rem", fontWeight: "600", marginBottom: "1.5rem" }}>🏆 Achievements</h3>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: "1rem" }}>
                  <div style={{
                    padding: "1rem",
                    background: "rgba(34, 197, 94, 0.1)",
                    border: "1px solid rgba(34, 197, 94, 0.3)",
                    borderRadius: "8px",
                    textAlign: "center",
                  }}>
                    <div style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>🌟</div>
                    <div style={{ color: "#9ca3af", fontSize: "0.85rem", fontWeight: "600" }}>Rising Star</div>
                    <div style={{ color: "#6b7280", fontSize: "0.75rem" }}>2000+ XP</div>
                  </div>
                  <div style={{
                    padding: "1rem",
                    background: "rgba(249, 115, 22, 0.1)",
                    border: "1px solid rgba(249, 115, 22, 0.3)",
                    borderRadius: "8px",
                    textAlign: "center",
                  }}>
                    <div style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>🔥</div>
                    <div style={{ color: "#9ca3af", fontSize: "0.85rem", fontWeight: "600" }}>On Fire</div>
                    <div style={{ color: "#6b7280", fontSize: "0.75rem" }}>7 Day Streak</div>
                  </div>
                  <div style={{
                    padding: "1rem",
                    background: "rgba(59, 130, 246, 0.1)",
                    border: "1px solid rgba(59, 130, 246, 0.3)",
                    borderRadius: "8px",
                    textAlign: "center",
                  }}>
                    <div style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>🎮</div>
                    <div style={{ color: "#9ca3af", fontSize: "0.85rem", fontWeight: "600" }}>Game Master</div>
                    <div style={{ color: "#6b7280", fontSize: "0.75rem" }}>3000+ Score</div>
                  </div>
                  <div style={{
                    padding: "1rem",
                    background: "rgba(168, 85, 247, 0.1)",
                    border: "1px solid rgba(168, 85, 247, 0.3)",
                    borderRadius: "8px",
                    textAlign: "center",
                  }}>
                    <div style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>📚</div>
                    <div style={{ color: "#9ca3af", fontSize: "0.85rem", fontWeight: "600" }}>Scholar</div>
                    <div style={{ color: "#6b7280", fontSize: "0.75rem" }}>10 Lessons</div>
                  </div>
                </div>
              </div>
            </div>

            {/* BOTTOM SECTION - ACTIVITY & UPCOMING */}
            <div style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "1.5rem",
            }}>
              {/* RECENT ACTIVITY */}
              <div style={{
                background: "rgba(15, 23, 42, 0.5)",
                border: "1px solid rgba(148, 163, 184, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <h3 style={{ color: "#f9fafb", fontSize: "1.2rem", fontWeight: "600", marginBottom: "1.5rem" }}>📈 Recent Activity</h3>
                {recentActivity.length === 0 ? (
                  <p style={{ color: "#6b7280", textAlign: "center" }}>No activity yet. Start learning!</p>
                ) : (
                  <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
                    {recentActivity.slice(0, 5).map((item) => (
                      <div key={item.id} style={{
                        padding: "1rem",
                        background: "rgba(56, 189, 248, 0.05)",
                        border: "1px solid rgba(56, 189, 248, 0.1)",
                        borderRadius: "8px",
                      }}>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start", marginBottom: "0.5rem" }}>
                          <div style={{ color: "#38bdf8", fontWeight: "600", fontSize: "0.9rem" }}>{item.type}</div>
                          <div style={{ color: "#6b7280", fontSize: "0.75rem" }}>
                            {new Date(item.created_at).toLocaleString()}
                          </div>
                        </div>
                        <p style={{ color: "#9ca3af", fontSize: "0.9rem", marginBottom: "0.25rem" }}>{item.description}</p>
                        <p style={{ color: "#6b7280", fontSize: "0.85rem" }}>📌 {item.subject}</p>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {/* UPCOMING SESSIONS */}
              <div style={{
                background: "rgba(15, 23, 42, 0.5)",
                border: "1px solid rgba(148, 163, 184, 0.2)",
                backdropFilter: "blur(10px)",
                borderRadius: "12px",
                padding: "1.5rem",
              }}>
                <h3 style={{ color: "#f9fafb", fontSize: "1.2rem", fontWeight: "600", marginBottom: "1.5rem" }}>📅 Upcoming Sessions</h3>
                {upcomingSessions.length === 0 ? (
                  <p style={{ color: "#6b7280", textAlign: "center" }}>No upcoming sessions. Book one now!</p>
                ) : (
                  <div style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
                    {upcomingSessions.slice(0, 5).map((session) => (
                      <div key={session.id} style={{
                        padding: "1rem",
                        background: "linear-gradient(135deg, rgba(168, 85, 247, 0.1), rgba(126, 34, 206, 0.05))",
                        border: "1px solid rgba(168, 85, 247, 0.2)",
                        borderRadius: "8px",
                      }}>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start", marginBottom: "0.5rem" }}>
                          <div style={{ color: "#d8b4fe", fontWeight: "600", fontSize: "0.9rem" }}>{session.subject}</div>
                          <div style={{ color: "#6b7280", fontSize: "0.75rem" }}>
                            {new Date(session.session_time).toLocaleString()}
                          </div>
                        </div>
                        <p style={{ color: "#9ca3af", fontSize: "0.9rem" }}>👨‍🏫 {session.tutorName}</p>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </>
        ) : (
          <p style={{ color: "#9ca3af", textAlign: "center" }}>No stats available. Please refresh.</p>
        )}
      </main>

      <style>{`
        .dashboard-page {
          display: flex;
          background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
          minHeight: 100vh;
        }

        .dashboard-main {
          flex: 1;
          overflow-y: auto;
        }
      `}</style>
    </div>
  );
}

export default Dashboard;
